function t(k){let value=text[lang][k]??k;if(mode!=='research'&&typeof value==='string')value=value.replace(/\s*[·(]?\s*L[1-7](?:[–-]L?[1-7])?\)?/g,'').replace(/BEFE/g,'').replace(/\s+([.:])/g,'$1').trim();return value}function pct(v){return v==null?'—':(v*100).toFixed(1)+'%'}function num(v){return v==null?'—':Number(v).toFixed(1).replace(/\.0$/,'')}
function message(code){if(code==='invalid:batches')return t('clinicstats_error');if(String(code).startsWith('past_cycle:')){const [,n,reason]=String(code).split(':'),fields={age_at_cycle:'age',okk_actual:'okk',blasts_actual:'blasts',amh_at_cycle:'amh',outcome:'outcome'};return t('pastattempt')+' '+n+': '+(fields[reason]?t('invalid')+': '+t(fields[reason]):t(reason==='age_future'?'pastagefuture':reason==='cascade'?'cascade':'invalid'))}const [key,field]=String(code).split(':');return (t(key==='busy'?'busyerror':key))+(field?': '+(t(field.startsWith('known_')?field.slice(6):field)):'')}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',6000)}
async function api(action,data={}){return DemoBridge.api(action,data)}
async function job(action,data={},type='busy'){const busy=$('#busy');busy.hidden=false;$('#busy-title').textContent=t(type);$('#busy-message').textContent=t(type==='busysetup'?'setupwait':'busyhelp');let elapsed=0;const clock=setInterval(()=>{$('#busy-time').textContent=(++elapsed)+' '+t('seconds')},1000);try{const task=await api(action,data);if(task.validation)return task;if(['calibrate_csv','lab_compatibility_report','batch'].includes(action)){let cancel=$('#cancel-job');if(!cancel){cancel=document.createElement('button');cancel.id='cancel-job';cancel.className='btn';busy.appendChild(cancel)}cancel.hidden=false;cancel.textContent=t('cancel');cancel.onclick=()=>guard(async()=>{await api('cancel_job',task);cancel.disabled=true})}while(true){await new Promise(r=>setTimeout(r,900));const state=await api('job',task);if(state.progress)document.querySelector('#busy-message').textContent=t('scored')+': '+state.progress.done+' / '+state.progress.total;if(state.state==='complete')return state.result;if(state.state==='failed')throw Error(state.error)}}finally{clearInterval(clock);if($('#cancel-job')){$('#cancel-job').hidden=true;$('#cancel-job').disabled=false}busy.hidden=true;$('#busy-time').textContent=''}}
function field(key,value='',min=0,max=100,step=1,help='',label=null){return `<label class="field">${esc(label||t(key))}<input name="${esc(key)}" type="number" min="${min}" max="${max}" step="${step}" value="${esc(value??'')}" placeholder="${esc(t('optional'))}">${help?`<small>${esc(help)}</small>`:''}</label>`}
function heading(title,intro,eyebrow=''){return `<div class="page-top"><div><div class="eyebrow">${esc(eyebrow||t('eyebrow'))}</div><h1>${esc(title)}</h1><p class="intro">${esc(intro)}</p></div></div>`}
function readForm(form){const data={};for(const [key,value] of new FormData(form))data[key]=value===''?null:value;return data}
function render(){document.documentElement.lang=lang;$('.edition').innerHTML=(lang==='ru'?'ДЛЯ КЛИНИК':'CLINIC EDITION')+' <span>7.1</span>';$('#language').value=lang;$('#local-label').textContent=t('local');$('#footer-text').textContent=t('footer');$('#clinic-name').textContent=state?.license?.clinic||'';$('#lic-badge').textContent=state?.license?.valid?t('activeuntil')+' '+state.license.expires:t('notactive');$('#breadcrumb').textContent=(lang==='ru'?'Рабочее место / ':'Workspace / ')+t('nav')[['patient','results','history','incoming','settings'].indexOf(page)];$('#nav').innerHTML=['patient','results','history','incoming','settings'].map((p,i)=>`<button data-page="${p}" class="${page===p?'active':''}"><span class="nav-number">0${i+1}</span>${esc(t('nav')[i])}</button>`).join('');
 if(page==='patient')renderPatient();if(page==='results')renderResults();if(page==='settings')renderSettings();if(page==='history')renderHistory();if(page==='incoming'&&typeof renderIncoming==='function')renderIncoming();}
function renderPatient(){
 const p={height_cm:165,weight_kg:60,age:35,amh:2.5,afc:15,attempt:1,sperm_source:'ejaculate',n_sim:2000,seed:42,...patient};
 $('#main').innerHTML=heading(t('title'),t('intro'))+(typeof incomingBanner==='function'?incomingBanner():'')+`<form id="patient-form"><section class="panel"><h2>${t('patient')}</h2><div class="form-grid"><label class="field">${t('patient_id')}<input name="patient_id" maxlength="80" value="${esc(p.patient_id||'')}" placeholder="IVF-2026-001"><small>${t('idhelp')}</small></label>${field('age',p.age,18,55,.1)}${field('amh',p.amh,0,30,.01)}${field('afc',p.afc,0,80,1,t('afchelp'))}${field('height_cm',p.height_cm,120,220,.1)}${field('weight_kg',p.weight_kg,30,200,.1)}<label class="field">${t('bmi')}<input name="bmi" readonly value="${esc(p.bmi??'')}" placeholder="${t('automatic')}"><small>${t(incomingContext&&p.bmi!=null&&!p.height_cm&&!p.weight_kg?'incoming_bmi_help':'bmihelp')}</small></label>${field('attempt',p.attempt,1,20)}${field('follicles',p.follicles,0,100)}${field('n_transfers_planned',p.n_transfers_planned,1,10,1,t('plannedhelp'))}<label class="field">${t('sperm_source')}<select name="sperm_source">${incomingContext&&!p.sperm_source?`<option value="" selected>${t('optional')}</option>`:''}${['ejaculate','donor','testicular_OA','epididymal','testicular_NOA'].map((v,i)=>`<option value="${v}" ${p.sperm_source===v?'selected':''}>${esc(t('sperm')[i])}</option>`).join('')}</select></label></div><details><summary>${t('observed')}</summary><p class="hint">${t('observedhelp')}</p><div class="form-grid">${['okk','mii','pn2','blasts','good','euploid'].map(k=>field('known_'+k,p['known_'+k],0,100,1,'',t(k))).join('')}</div></details><details><summary>${t('expertsettings')}</summary><div class="form-grid">${field('n_sim',p.n_sim,500,10000,500)}${field('seed',p.seed,0,2147483647)}</div></details><div class="actions"><button class="btn primary" type="submit">${t('run')} →</button><span class="hint">${t('privacy')}</span></div></section></form>`;
 const form=$('#patient-form'),h=form.elements.height_cm,w=form.elements.weight_kg,importedBMI=!!incomingContext&&p.bmi!=null&&!p.height_cm&&!p.weight_kg;h.required=w.required=!importedBMI;
 form.elements.bmi.readOnly=!importedBMI;
 if(incomingContext){form.elements.patient_id.readOnly=true;for(const k of ['age','amh','afc','attempt','sperm_source'])form.elements[k].required=true;if($('#incoming-detach'))$('#incoming-detach').onclick=()=>{patient=readForm(form);incomingContext=null;renderPatient()};}
 function bmi(){if(h.value&&w.value)form.elements.bmi.value=(Number(w.value)/(Number(h.value)/100)**2).toFixed(2);else if(!importedBMI)form.elements.bmi.value=''}h.oninput=w.oninput=bmi;bmi();
 form.onsubmit=async e=>{e.preventDefault();patient=readForm(form);try{const previousId=result?.patient_id;result=await job('calculate',{...patient,...(incomingContext?{_incoming:{id:incomingContext.id,revision:incomingContext.revision}}:{})});incomingContext=null;if(!result.patient_id||result.patient_id!==previousId)draftPast=[];narrative='';page='results';render()}catch(err){toast(message(err.message))}};
}
function renderResults(){
 if(!result){$('#main').innerHTML=heading(t('empty'),t('emptytext'));return}
 const r=result,f=r.fusion||{},max=Math.max(1,...r.stages.map(v=>v.median||0));
 $('#main').innerHTML=heading(t('results'),`${r.patient_id||'—'} · ${r.created}`,t('current'))+`<div class="tabs">${['clinical','extended','research'].map(v=>`<button data-mode="${v}" class="${mode===v?'active':''}">${t(v)}</button>`).join('')}<a id="interpretation-open" role="button" href="/interpretation#${esc(token)}|${esc(r.id)}|${lang}" target="ivf-interpretation-${esc(r.id)}">${t('interpretation')} ↗</a></div>${Object.entries(r.layers).some(([k,v])=>!v&&!(k==='L5'&&r.csdi_applicability?.reason==='no_2pn'))?`<div class="note">${t('partial')}</div>`:''}${oodNotice(r)}<div class="forecast-layout ${mode==='research'?'with-layers':''}">${primaryHTML(r)}${mode==='research'?layerCards(r):''}</div><section class="panel"><h2>${t('stages')}</h2><p class="hint">${t('stagehelp')}</p>${r.stages.map((v,i)=>`<div class="stage-row"><span>${t(v.key==='euploid'&&r.transfer_scenario==='all_blastocysts'?'euploid_nopgt':v.key)}</span><div class="bar"><span style="width:${(v.median||0)/max*100}%;opacity:${1-i*.08}"></span></div><strong>${num(v.median)}</strong><small>${num(v.low)} – ${num(v.high)}</small></div>`).join('')}${r.transferable?`<p class="hint">${t('transferablehelp')}</p><div class="stage-row"><span>${t('warmed')}</span><div class="bar"><span style="width:${Math.min(100,(r.transferable.median||0)/max*100)}%"></span></div><strong>${num(r.transferable.median)}</strong><small>${num(r.transferable.low)} – ${num(r.transferable.high)}</small></div>`:''}</section>${mode!=='clinical'?extendedHTML():''}${mode==='research'?graphPanel(r):''}<div class="note">${t('note')}</div><div class="actions"><button class="btn primary" id="pdf">↓ ${t('pdf')}</button><button class="btn" id="save">${t('save')}</button><button class="btn" data-page="patient">${t('new')}</button></div>`;
 $('#interpretation-open').onclick=e=>{if(state?.native_windows){e.preventDefault();guard(()=>api('open_interpretation',{id:r.id,language:lang}))}};
 $('#pdf').onclick=()=>guard(async()=>{const out=await api('export_pdf',{id:r.id,language:lang,mode});downloadText(Uint8Array.from(atob(out.content),c=>c.charCodeAt(0)),out.filename,'application/pdf')});
 $('#save').onclick=()=>guard(async()=>{await api('save',{id:r.id});toast(t('saved'))});
 if(mode!=='clinical')bindExtended();if(mode==='research')drawPatientGraph(r);
 if($('#technical-download'))$('#technical-download').onclick=()=>downloadText(JSON.stringify(r.technical,null,2),'IVF-research.json','application/json');
}
function extendedHTML(){
 const r=result;return distributionPanel()+clusterPanel(r)+bankingPanel()+stimulationPanel(r)+riskPanel()+`<section class="panel"><h2>${t('planning')}</h2><p class="intro">${t('planninghelp')}</p><form id="trp-form"><div class="form-grid">${field('max_future_cycles',6,1,10)}${field('min_cycle_percent',3,0,100,.1)}${field('cycle_interval_mo',3,1,24,.5)}${field('amh_min',.1,.01,5,.01)}${field('age_max',45,35,55,.5)}${field('n_trajectories',5000,1000,10000,1000)}</div><details><summary>${t('past')}</summary><div id="past-cycles"></div><button class="btn" type="button" id="add-past">+ ${t('addpast')}</button></details><div class="actions"><button class="btn primary">${t('plan')} →</button></div></form><div id="trp-output">${r.trp?trpHTML(r.trp):''}</div></section><section class="panel"><h2>${t('technical')}</h2>${researchHTML(r)}</section>`;
}
function trpHTML(r){const values=r.p_cum_by_cycle,w=780,h=180,pad=35,x=i=>pad+i*(w-2*pad)/Math.max(1,values.length-1),y=p=>h-pad-(h-2*pad)*p;return `<div class="note">${t('trpnote')}</div><h3>${t('cumulative')}</h3><svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${t('cumulative')}"><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" class="chart-axis"/><polyline points="${values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" class="chart-line" stroke-width="3"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" class="chart-dot"/><text x="${x(i)}" y="${y(v)-13}" text-anchor="middle" class="chart-value">${pct(v)}</text><text x="${x(i)}" y="${h-10}" text-anchor="middle">${i+1}</text>`).join('')}</svg><div class="metric-row"><span>${t('trpanchor')}</span><strong>${pct(r.anchor_probability)}</strong></div><div class="metric-row"><span>${t('window')}</span><strong>${num(r.window_years_p50)}</strong></div>${r.n_past_cycles?`<div class="metric-row"><span>${t('pastcount')}</span><strong>${r.n_past_cycles}</strong></div>`:''}`}
function bindExtended(){
 renderPast();$('#distribution-form').onsubmit=e=>{e.preventDefault();guard(async()=>{result.distribution=await job('distribution',{id:result.id,...readForm(e.target)});$('#distribution-output').innerHTML=distributionHTML(result.distribution)})};
 $('#add-past').onclick=()=>{if(draftPast.length<10){capturePast();draftPast.push({age_at_cycle:Math.max(18,Math.round((Number(result.patient.age)-1)*10)/10)});renderPast()}};
 $('#trp-form').onsubmit=e=>{e.preventDefault();capturePast();guard(async()=>{result.trp=await job('trp',{...readForm(e.target),id:result.id,past_cycles:draftPast});if(result.trp.past_cycles){draftPast=result.trp.past_cycles;renderPast()}$('#trp-output').innerHTML=trpHTML(result.trp)})};
 const id=result.id;$('#stim').onclick=()=>guard(async()=>{const r=await api('stimulation',{id});if(result.id===id){result.stimulation=r;if($('#stim-output')){$('#stim-output').innerHTML=stimulationHTML(r);toast(t('guidance_updated'))}}});bindBanking();
}
function renderPast(){const target=$('#past-cycles');if(!target)return;target.innerHTML=(draftPast.length?`<p class="hint">${t('pasthelp')}</p>`:'')+draftPast.map((p,i)=>`<div data-past="${i}" class="panel past-cycle"><div class="past-head"><h3>${t('pastattempt')} ${i+1}</h3><button type="button" class="icon-btn" data-remove-past="${i}" title="${t('removepast')}" aria-label="${t('removepast')} ${i+1}">×</button></div><div class="form-grid">${field('age_at_cycle',p.age_at_cycle,18,55,.1,'',t('age'))}${field('okk_actual',p.okk_actual,0,100,1,'',t('okk'))}${field('blasts_actual',p.blasts_actual,0,100,1,'',t('blasts'))}${field('amh_at_cycle',p.amh_at_cycle,0,30,.01,'',t('amh'))}<label class="field">${t('outcome')}<select name="outcome"><option value="">${t('unknown')}</option><option value="1" ${p.outcome==1?'selected':''}>${t('yes')}</option><option value="0" ${p.outcome==0&&p.outcome!=null?'selected':''}>${t('no')}</option></select></label></div></div>`).join('')}
function capturePast(){draftPast=[...document.querySelectorAll('[data-past]')].map(node=>Object.fromEntries([...node.querySelectorAll('[name]')].map(el=>[el.name,el.value===''?null:el.value])))}
function renderSettings(){const lic=state?.license,llm=state?.llm;$('#main').innerHTML=heading(t('settings'),t('settingsintro'))+`<div class="settings-page"><div class="settings-preparation"><section class="panel"><div class="step"><span class="step-number">1</span><div><h2>${t('license')}</h2><p>${t('licensehelp')}</p>${lic?.valid?`<span class="badge">${t('activeuntil')} ${esc(lic.expires)}</span>`:''}</div></div><form id="license-form"><label class="field">${t('key')}<textarea name="key" rows="3" placeholder="IVF-…" maxlength="16384" required spellcheck="false"></textarea></label><div class="actions"><button class="btn primary">${t('activate')}</button></div></form></section><section class="panel"><div class="step"><span class="step-number">2</span><div><h2>${t('llmsetup')}</h2><p>${t('llmsetuphelp')}</p><span class="badge ${llm?.ready?'':'warn'}">${t(llm?.ready?'llmready':'llmabsent')}</span></div></div><div class="status-line"><span>Gemma 4</span><span>12B · QAT</span></div><div class="actions"><button class="btn" id="prepare">${t('prepare')}</button></div></section></div><section class="panel settings-computer"><h2>${t('hardware')}</h2><p class="intro">${t('hardwaretext')}</p><span class="hint">${esc(state?.version||'')} · ${esc(state?.revision||'')}</span><p class="hint">${esc(state?.source_root||'')}</p></section>${settingsExtra()}${typeof integrationSettingsHTML==='function'?integrationSettingsHTML():''}</div>`;bindSettingsExtra();if(typeof bindIntegrationSettings==='function')bindIntegrationSettings();
 $('#license-form').onsubmit=e=>{e.preventDefault();guard(async()=>{await api('activate',readForm(e.target));state=await api('status');render()})};$('#prepare').onclick=()=>guard(async()=>{await job('prepare_llm',{},'busysetup');state=await api('status');render();toast(t('prepared'))});}
async function renderHistory(){$('#main').innerHTML=heading(t('history'),t('historyintro'))+`<div class="history-tools" id="history-tools" hidden><button type="button" class="btn" id="history-csv">${t('historycsv')}</button><small>${t('historycsvhelp')}</small></div><section class="panel" id="history-list"></section>`;$('#history-csv').onclick=()=>guard(async()=>{const out=await api('export_history_csv');downloadText(Uint8Array.from(atob(out.content),c=>c.charCodeAt(0)),out.filename,'text/csv');toast(t('historycsvdone')+': '+out.rows)});$('#history-list').onclick=e=>{const row=e.target.closest('.history-row');if(!row)return;const ask=e.target.closest('[data-delete-record]'),cancel=e.target.closest('[data-cancel-delete]'),yes=e.target.closest('[data-confirm-delete]');if(ask||cancel){row.querySelector('.history-actions').hidden=!!ask;row.querySelector('.history-confirm').hidden=!ask}if(yes)guard(async()=>{yes.disabled=true;try{await api('delete_history',{id:yes.dataset.confirmDelete});toast(t('historydeleted'))}finally{if(page==='history')renderHistory()}})};try{const rows=await api('list_history');if(page!=='history')return;$('#history-tools').hidden=!rows.length;$('#history-list').innerHTML=rows.length?rows.map(r=>`<div class="history-row"><div class="meta"><strong>${esc(r.patient_id||'—')}</strong><small>${esc(r.created)} · ${t('age')}: ${num(r.patient.age)}</small></div><strong>${pct(r.probability!==undefined?r.probability:r.headline)}</strong><div class="history-actions"><button class="btn" data-record="${r.id}">${t('open')}</button><button type="button" class="icon-btn" data-delete-record="${r.id}" title="${t('historydelete')}" aria-label="${t('historydelete')}">×</button></div><div class="history-confirm" hidden><span>${t('historydeleteask')}</span><button type="button" class="btn danger" data-confirm-delete="${r.id}">${t('historydeleteyes')}</button><button type="button" class="btn" data-cancel-delete>${t('historydeleteno')}</button></div></div>`).join(''):`<p class="intro">${t('emptyhistory')}</p>`}catch(err){toast(message(err.message))}}
async function guard(fn){try{await fn()}catch(err){toast(message(err.message))}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){if(page==='patient'&&$('#patient-form'))patient=readForm($('#patient-form'));page=nav.dataset.page;render()}const tab=e.target.closest('[data-mode]');if(tab){mode=tab.dataset.mode;renderResults()}const record=e.target.closest('[data-record]');if(record)guard(async()=>{incomingContext=null;result=await api('load_history',{id:record.dataset.record});draftPast=result.trp?.past_cycles||[];patient={...result.patient,patient_id:result.patient_id};narrative='';page='results';render()});const remove=e.target.closest('[data-remove-past]');if(remove){capturePast();draftPast.splice(Number(remove.dataset.removePast),1);renderPast()}});
$('#language').onchange=e=>{if(page==='patient'&&$('#patient-form'))patient=readForm($('#patient-form'));lang=e.target.value;localStorage.setItem('ivf-language',lang);guard(()=>api('set_language',{language:lang}));narrative='';render()};


Object.assign(text.ru,{distribution:'Распределение прогноза BEFE',distributionhelp:'Оценка по отдельным сценариям текущего цикла: сценарии без переноса учитываются в вероятности за цикл, вероятность при переносе оценивается по сценариям с переносом. Большее число сценариев увеличивает время расчёта.',n_samples:'Сценариев для оценки',distributionrun:'Построить распределение',percycle:'Хотя бы одна беременность за цикл',pertransfer:'Беременность при одном переносе',mean:'Среднее',median:'Медиана',spread:'Центральные 95% сценариев',failures:'Ожидаемая доля циклов без беременности',notransfer:'Доля сценариев без переноса',distributionnote:'Интервал отражает разброс модельных сценариев, а не доверительный интервал точности модели. Расчёт за цикл учитывает все доступные переносы (бластоцисты среднего качества — с поправкой по данным) и предполагает независимость их исходов при заданной вероятности. Неопределённость параметров обученных моделей здесь не оценивается.',distribution_recalculate:'Для построения распределения повторите расчёт с параметрами сохранённой записи.',distribution_failed:'Не удалось оценить все сценарии. Подробности сохранены в журнале.',scored:'Оценено сценариев',prior:'Вклад исходного прогноза',evidence:'Вклад дополнительных моделей',technicaldownload:'Скачать данные исследования (JSON)',l1transfer:'Исходная вероятность при переносе · L1–L4',l1cycle:'Беременность за цикл · L1–L4',technicalfile:'Файл содержит исходные обозначения моделей и предназначен для анализа специалистом.',stagefamily:'Модель образования бластоцист',betanote:'Бета-биномиальная; среднее и дисперсия сохранены из прежней модели. Новая клиническая подгонка не выполнялась.'});
Object.assign(text.en,{distribution:'BEFE forecast distribution',distributionhelp:'Score individual scenarios for the current cycle: scenarios without a transfer count towards the per-cycle probability, and the per-transfer probability uses scenarios with a transfer. More scenarios increase calculation time.',n_samples:'Scenarios to score',distributionrun:'Build distribution',percycle:'At least one pregnancy per cycle',pertransfer:'Pregnancy per single transfer',mean:'Mean',median:'Median',spread:'Central 95% of scenarios',failures:'Expected fraction of cycles without pregnancy',notransfer:'Fraction of scenarios without a transfer',distributionnote:'The interval describes model scenario spread, not a confidence interval for model accuracy. The cycle estimate includes all available transfers (fair-quality blastocysts with a data-derived adjustment) and assumes independent outcomes conditional on the probability. Trained model parameter uncertainty is not estimated.',distribution_recalculate:'Recalculate using the saved patient parameters before building a distribution.',distribution_failed:'Some scenarios could not be scored. Details are in the application log.',scored:'Scenarios scored',prior:'Prior contribution',evidence:'Additional model contribution',technicaldownload:'Download research data (JSON)',l1transfer:'Prior per-transfer probability · L1–L4',l1cycle:'Pregnancy per cycle · L1–L4',technicalfile:'The file contains original model identifiers for specialist analysis.',stagefamily:'Blastulation model',betanote:'Beta-binomial; mean and variance retained from the previous model. No new clinical fitting was performed.'});
function distributionPanel(){return `<section class="panel"><h2>${t('distribution')}</h2><p class="intro">${t('distributionhelp')}</p><form id="distribution-form"><div class="inline-form">${field('n_samples',result.distribution?.n_scored||400,100,2000,100)}<button class="btn primary">${t('distributionrun')}</button></div></form><div id="distribution-output">${result.distribution?distributionHTML(result.distribution):''}</div></section>`}
function distributionHTML(d){function chart(s,label){const counts=s.histogram.counts,max=Math.max(1,...counts);return `<h3>${label}</h3><svg class="chart" viewBox="0 0 780 190" role="img" aria-label="${esc(label)}">${counts.map((v,i)=>`<rect x="${35+i*35}" y="${150-v/max*115}" width="31" height="${v/max*115}" rx="3" class="chart-bar"><title>${i*5}–${(i+1)*5}%: ${v}</title></rect>`).join('')}<line x1="35" y1="150" x2="735" y2="150" class="chart-axis"/>${[0,25,50,75,100].map(v=>`<text x="${35+7*v}" y="175" text-anchor="middle">${v}%</text>`).join('')}</svg><div class="metric-row"><span>${t('mean')} / ${t('median')}</span><strong>${pct(s.mean)} / ${pct(s.median)}</strong></div><div class="metric-row"><span>${t('spread')}</span><strong>${pct(s.low)} – ${pct(s.high)}</strong></div>`}return chart(d.per_cycle,t('percycle'))+(d.per_transfer?`<details><summary>${t('pertransfer')}</summary>${chart(d.per_transfer,t('pertransfer'))}</details>`:'')+`<div class="metric-row"><span>${t('failures')}</span><strong>${pct(d.expected_failure_fraction)}</strong></div><div class="metric-row"><span>${t('notransfer')}</span><strong>${pct(d.no_transfer_fraction)}</strong></div><div class="hint">${t('scored')}: ${d.n_scored} / ${d.n_available}</div><div class="note">${t('distributionnote')}</div>`}
function researchHTML(r){const f=r.fusion||{},post=r.technical?.posterior;return `${post?`<h3>${t('clinicprior')}</h3><div class="metric-row"><span>${t('mean')}</span><strong>${pct(post.mean)}</strong></div><div class="metric-row"><span>${t('interval')}</span><strong>${pct(post.ci_low)} – ${pct(post.ci_high)}</strong></div><p class="hint">${t('clinicpriorhelp')}</p>`:''}<div class="metric-row"><span>${t('l1transfer')}</span><strong>${pct(r.per_transfer)}</strong></div><div class="metric-row"><span>${t('l1cycle')}</span><strong>${pct(r.technical?.pipeline?.p_overall_cycle)}</strong></div><div class="metric-row"><span>${t('prior')}</span><strong>${pct(f.prior_pull)}</strong></div><div class="metric-row"><span>${t('evidence')}</span><strong>${pct(f.evidence_pull)}</strong></div><h3>${t('stagefamily')}</h3><p class="intro">${t('betanote')}</p><div class="actions"><button class="btn" id="technical-download">${t('technicaldownload')}</button></div><p class="hint">${t('technicalfile')}</p>`}
function downloadText(value,name,type){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function protocolLabel(value){if(lang==='en')return value;const labels={'GnRH-antagonist':'С антагонистом ГнРГ','GnRH-agonist':'С агонистом ГнРГ','PPOS':'С прогестиновой поддержкой','mild':'Мягкая стимуляция'};return labels[value]||value}

Object.assign(text.ru,{clinicprior:'Статистика клиники',clinicpriorhelp:'Исходная оценка L1–L4 может учитывать число беременностей среди переносов в вашей клинике. Это обновление исходной вероятности, а не переобучение нейросетей. Используйте одинаковое определение исхода для всех периодов.',batches:'По строке на период: беременности, переносы',useprior:'Учитывать статистику клиники',apply:'Сохранить настройку',batchtitle:'Расчёт группы пациенток',batchhelp:'CSV в UTF-8, до 200 строк. Обязательные столбцы: age, amh, afc, bmi. Можно добавить patient_id, attempt, n_sim и известные этапы known_okk, known_mii, known_pn2, known_blasts, known_good, known_euploid. Неизвестные значения оставляйте пустыми.',batchrun:'Рассчитать и скачать CSV',csv:'Данные CSV',inverse:'Ориентир накопления зрелых ооцитов',inversenote:'Число MII для получения заданного числа эуплоидных эмбрионов по модели Esteves. Заголовки столбцов — вероятность достижения цели.',embryotarget:'Цель, эмбрионов'});
Object.assign(text.en,{clinicprior:'Clinic statistics',clinicpriorhelp:'The L1–L4 prior can incorporate pregnancies among transfers in your clinic. This updates the prior probability; it does not retrain neural networks. Use the same outcome definition across periods.',batches:'One period per line: pregnancies, transfers',useprior:'Use clinic statistics',apply:'Save settings',batchtitle:'Batch patient calculations',batchhelp:'UTF-8 CSV, up to 200 rows. Required columns: age, amh, afc, bmi. Optional: patient_id, attempt, n_sim, known_okk, known_mii, known_pn2, known_blasts, known_good, known_euploid. Leave unknown observations blank.',batchrun:'Calculate and download CSV',csv:'CSV data',inverse:'Mature oocyte banking estimate',inversenote:'MII count to obtain the target number of euploid embryos under the Esteves model. Column headings show the probability of reaching the target.',embryotarget:'Target embryos'});
function bankingTable(b){if(!b.mii_table)return '';return `<details><summary>${t('inverse')}</summary><p class="hint">${t('inversenote')}</p><table class="data-table numeric"><thead><tr><th>${t('embryotarget')}</th>${b.confidences.map(c=>`<th>${pct(c)}</th>`).join('')}</tr></thead><tbody>${b.k_targets.map(k=>`<tr><td>${k}</td>${b.confidences.map(c=>`<td>${b.mii_table[k][String(c)]??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`}
function settingsExtra(){if(!state?.license?.valid)return '';return revisionSettings()+`<section class="panel"><h2>${t('clinicprior')}</h2><p class="intro">${t('clinicpriorhelp')}</p><form id="prior-form"><label class="field">${t('batches')}<textarea id="prior-batches" rows="4" placeholder="25, 60"></textarea></label><label class="settings-check"><input id="prior-enabled" type="checkbox"> ${t('useprior')}</label><div class="actions"><button class="btn">${t('apply')}</button><button class="btn" type="button" id="prior-reset">${t('resetstats')}</button></div></form></section><section class="panel"><h2>${t('batchtitle')}</h2><p class="intro">${t('batchhelp')}</p><form id="batch-form"><div class="actions"><label class="btn">${t('csvfile')}<input id="csv-file" type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden></label><button type="button" class="btn" id="csv-template">${t('csvtemplate')}</button><button type="button" class="btn" id="xlsx-template">${t('xlsxtemplate')}</button></div><label class="field table-preview">${t('table_preview')}<textarea name="csv" rows="6" wrap="off" spellcheck="false" required placeholder="patient_id,age,amh,afc,bmi&#10;TEST-001,35,2.5,15,23"></textarea></label><div class="actions settings-export"><label class="field">${t('output_format')}<select name="output_format"><option value="csv">CSV</option><option value="xlsx">Excel (.xlsx)</option></select></label><button class="btn">${t('batchrun')}</button></div></form></section>`}
function bindSettingsExtra(){bindRevisionSettings();if(!$('#prior-form'))return;$('#prior-reset').onclick=()=>guard(async()=>{await api('clinic_settings_reset');renderSettings();toast(t('statsreset'))});$('#csv-file').onchange=()=>guard(async()=>{const f=$('#csv-file').files[0];if(!f)return;document.querySelector('[name=csv]').value='';const out=await readClinicFile(f,'batch');document.querySelector('[name=csv]').value=out.csv;document.querySelector('[name=output_format]').value=out.format;toast(t('table_loaded')+': '+out.rows)});$('#csv-template').onclick=()=>guard(()=>downloadTemplate('batch'));$('#xlsx-template').onclick=()=>guard(()=>downloadTemplate('batch','xlsx'));guard(async()=>{const v=await api('clinic_settings');if($('#prior-batches')){$('#prior-batches').value=v.batches.map(r=>r.join(', ')).join('\n');$('#prior-enabled').checked=v.enabled}});$('#prior-form').onsubmit=e=>{e.preventDefault();guard(async()=>{const raw=$('#prior-batches').value.trim(),batches=raw?raw.split(/\r?\n/).map(line=>line.split(',').map(v=>Number(v.trim()))):[];await api('clinic_settings',{save:true,enabled:$('#prior-enabled').checked,batches});toast(t('saved'))})};$('#batch-form').onsubmit=e=>{e.preventDefault();guard(async()=>{const out=await job('batch',readForm(e.target));const bytes=Uint8Array.from(atob(out.content),c=>c.charCodeAt(0));downloadText(bytes,out.filename,out.mime||'text/csv;charset=utf-8');toast(t('table_export_ready')+': '+out.filename)})}}

Object.assign(text.ru,{risks:'Модельные индикаторы риска',noblast:'Цикл без бластоцист',nogood:'Цикл без бластоцист хорошего качества',moderateohss:'Получение 15–19 ооцитов (повышенный риск СГЯ)',severeohss:'Получение ≥20 ооцитов (высокий риск СГЯ)',notransfer:'Цикл без эмбриона для переноса',ohssobserved:'Получено ооцитов',ohsszone_high:'зона высокого риска СГЯ (≥20)',ohsszone_moderate:'зона повышенного риска СГЯ (15–19)',ohsszone_low:'ниже зон риска СГЯ (<15)',risknote:'Для СГЯ показана вероятность получить указанное число ооцитов, а не вероятность развития СГЯ. Оценки циклов без бластоцист и без переноса модельные и требуют проверки калибровки на данных клиники.',csvfile:'Открыть файл CSV',csvtemplate:'Скачать шаблон CSV'});
Object.assign(text.en,{risks:'Model risk indicators',noblast:'Cycle without blastocysts',nogood:'Cycle without good-quality blastocysts',moderateohss:'Retrieval of 15–19 oocytes (increased OHSS risk)',severeohss:'Retrieval of ≥20 oocytes (high OHSS risk)',notransfer:'Cycle without an embryo for transfer',ohssobserved:'Oocytes retrieved',ohsszone_high:'high OHSS-risk zone (≥20)',ohsszone_moderate:'increased OHSS-risk zone (15–19)',ohsszone_low:'below OHSS-risk zones (<15)',risknote:'For OHSS, the probability of retrieving the stated oocyte count is shown, not the probability of developing OHSS. No-blastocyst and no-transfer estimates are model-based and require calibration assessment on clinic data.',csvfile:'Open CSV file',csvtemplate:'Download CSV template'});
function riskPanel(){const e=result.empty||{},r=result.risks||{},okk=result.patient?.known_okk;const rows=[['noblast',e.p_no_blast],['nogood',e.p_no_good_blast],...(e.p_no_transfer==null?[]:[['notransfer',e.p_no_transfer]])];const zone=okk==null?'':okk>=20?'ohsszone_high':okk>=15?'ohsszone_moderate':'ohsszone_low';const ohss=okk==null?[['moderateohss',r.p_moderate_ohss],['severeohss',r.p_severe_ohss]].map(([k,v])=>`<div class="metric-row"><span>${t(k)}</span><strong>${pct(v)}</strong></div>`).join(''):`<div class="metric-row"><span>${t('ohssobserved')}: ${num(okk)}</span><strong>${t(zone)}</strong></div>`;return `<section class="panel"><h2>${t('risks')}</h2>${rows.map(([k,v])=>`<div class="metric-row"><span>${t(k)}</span><strong>${pct(v)}</strong></div>`).join('')}${ohss}<div class="note">${t('risknote')}</div></section>`}

Object.assign(text.ru,{max_future_cycles:'Попыток в плане',min_cycle_percent:'Порог вероятности на цикл, %',planninghelp:'TRP оценивает план новых циклов при текущих возрасте и овариальном резерве. Известные результаты текущего цикла не переносятся на будущие попытки. История сохраняется как контекст для врача.',window:'Расчётный горизонт по возрасту и АМГ, лет',clinicpriorhelp:'Число беременностей среди переносов используется в дополнительной байесовской оценке исследовательского режима. Используйте одинаковое определение исхода для всех периодов.',clinicprior:'Дополнительная оценка по статистике клиники',trpnote:'Сценарная оценка хотя бы одной беременности. Исходная вероятность — показанная вероятность беременности за цикл; при подтверждённом отсутствии переноса берётся новый цикл. Порог вероятности, возраст и АМГ ограничивают план. Показатель не оценивает рождение ребёнка.'});
